/*
Uninity corresponds to the minimum Horton-Strahler number over all choices
of root. For a rooted tree:
- leaf => 0
- let mx be maximum child value
  if mx appears once, node value = mx
  else node value = mx + 1

For an unrooted tree, the minimum possible root value is attained at a center
of the "equal-height" reduction process, and can be computed by repeatedly
peeling leaves while propagating these values inward.

This implementation performs a standard leaf-removal DP:
each removed leaf contributes its current value to its remaining neighbor.
For each vertex we keep the two largest contributed values and the count of
the largest one. When a vertex becomes a leaf in the remaining graph, its own
value is determined by those contributions:
- no contributions => 0
- largest contributed value appears once => that value
- otherwise => that value + 1

At the end, 1 or 2 vertices remain:
- one vertex: answer is its computed value
- two adjacent vertices: root on either side joining the other as child, so
  answer is combine(value[a], value[b]):
    if value[a] == value[b] => value[a] + 1
    else max(value[a], value[b])
*/

static void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

typedef struct Info {
    int max1;   // largest contributed value
    int cnt1;   // count of largest contributed value
    int max2;   // second largest contributed value
} Info;

static Info *info_arr;

static void add_contribution(int v, int x) {
    Info *inf = &info_arr[v];
    if (x > inf->max1) {
        inf->max2 = inf->max1;
        inf->max1 = x;
        inf->cnt1 = 1;
    } else if (x == inf->max1) {
        inf->cnt1++;
    } else if (x > inf->max2) {
        inf->max2 = x;
    }
}

static int finalize_value(int v) {
    Info *inf = &info_arr[v];
    if (inf->max1 < 0) return 0;          // original isolated leaf in remaining tree
    if (inf->cnt1 >= 2) return inf->max1 + 1;
    return inf->max1;
}

int main(void) {
    if (scanf("%d", &N) != 1) return 0;

    if (N == 1) {
        printf("0\n");
        return 0;
    }

    edges = (Edge *)malloc((2 * (N - 1)) * sizeof(Edge));
    head = (int *)malloc((N + 1) * sizeof(int));
    deg = (int *)malloc((N + 1) * sizeof(int));
    value = (int *)malloc((N + 1) * sizeof(int));
    info_arr = (Info *)malloc((N + 1) * sizeof(Info));

    for (int i = 1; i <= N; i++) {
        head[i] = -1;
        deg[i] = 0;
        info_arr[i].max1 = -1;
        info_arr[i].cnt1 = 0;
        info_arr[i].max2 = -1;
    }

    for (int i = 0; i < N - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
        deg[u]++;
        deg[v]++;
    }

    int *queue = (int *)malloc((N + 5) * sizeof(int));
    int qh = 0, qt = 0;

    for (int i = 1; i <= N; i++) {
        if (deg[i] <= 1) queue[qt++] = i;
    }

    int remaining = N;
    int *removed = (int *)calloc(N + 1, sizeof(int));

    while (remaining > 2) {
        int layer_size = qt - qh;
        remaining -= layer_size;

        for (int it = 0; it < layer_size; it++) {
            int u = queue[qh++];
            removed[u] = 1;
            value[u] = finalize_value(u);

            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                if (removed[v]) continue;

                add_contribution(v, value[u]);
                deg[v]--;
                if (deg[v] == 1) {
                    queue[qt++] = v;
                }
            }
        }
    }

    int centers[2], csz = 0;
    for (int i = 1; i <= N; i++) {
        if (!removed[i]) centers[csz++] = i;
    }

    int ans;
    if (csz == 1) {
        ans = finalize_value(centers[0]);
    } else {
        int a = centers[0], b = centers[1];
        int va = finalize_value(a);
        int vb = finalize_value(b);
        ans = (va == vb) ? (va + 1) : (va > vb ? va : vb);
    }

    printf("%d\n", ans);

    free(edges);
    free(head);
    free(deg);
    free(value);
    free(info_arr);
    free(queue);
    free(removed);

    return 0;
}

