#include <bits/stdc++.h>
using namespace std;

/*
Uninity definition:
- A single vertex has uninity 0.
- If we take zero or more trees of uninity k and connect one chosen vertex
  from each of them to a new vertex, the resulting tree has uninity k+1.

We need the minimum k for a given tree.

Key observation:
For a rooted tree, let f(u, p) be the minimum uninity of the subtree rooted at u
when considering children away from parent p.

If u is a leaf => f = 0.

Otherwise, suppose children subtrees have values x1, x2, ..., xm.
To build the subtree at u as one tree of minimum uninity:
all child components attached to u must be trees of the same uninity t,
possibly after "padding" smaller ones upward. Since any tree of uninity a
can be transformed into one of any larger uninity b by repeatedly applying
the construction with zero attached subtrees, the needed t is max(xi).
Then attaching them to u gives value t+1.

So:
f(u,p) = 0 if no children
f(u,p) = 1 + max f(v,u) over children v

Thus for a chosen root r, the tree's uninity is exactly the height
(max distance from r to any vertex). We need the minimum over all roots,
which is the tree radius.

For a tree, radius = ceil(diameter / 2).

So compute diameter and output (diameter + 1) / 2.
*/

pair<int, vector<int>> bfs_far(int start, const vector<vector<int>>& g) {
    int n = (int)g.size() - 1;
    vector<int> dist(n + 1, -1);
    queue<int> q;
    q.push(start);
    dist[start] = 0;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : g[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }

    int far = start;
    for (int i = 1; i <= n; ++i) {
        if (dist[i] > dist[far]) far = i;
    }
    return {far, dist};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<int>> g(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    if (N == 1) {
        cout << 0 << '\n';
        return 0;
    }

    auto [a, _] = bfs_far(1, g);
    auto [b, dist] = bfs_far(a, g);
    int diameter = dist[b];

    cout << (diameter + 1) / 2 << '\n';
    return 0;
}

