public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N;
    static ArrayList<Integer>[] g;
    static int[] parent;
    static int[] order;
    static int[] degree;
    static int[] val;
    static int[] cnt;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();

        g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            g[u].add(v);
            g[v].add(u);
        }

        if (N == 1) {
            System.out.println(0);
            return;
        }

        parent = new int[N + 1];
        order = new int[N];
        buildOrderIterative(1);

        degree = new int[N + 1];
        for (int i = 1; i <= N; i++) degree[i] = g[i].size();

        val = new int[N + 1];
        cnt = new int[N + 2];

        int answer = 0;

        for (int idx = N - 1; idx >= 0; idx--) {
            int u = order[idx];

            int childCount = degree[u] - (parent[u] == 0 ? 0 : 1);
            if (childCount == 0) {
                val[u] = 0;
                answer = Math.max(answer, 0);
                continue;
            }

            int maxv = -1;
            for (int v : g[u]) {
                if (v == parent[u]) continue;
                int x = val[v];
                cnt[x]++;
                if (x > maxv) maxv = x;
            }

            int mex = 0;
            while (cnt[mex] > 0) mex++;

            for (int v : g[u]) {
                if (v == parent[u]) continue;
                cnt[val[v]]--;
            }

            val[u] = mex + 1;
            answer = Math.max(answer, val[u]);
        }

        System.out.println(answer);
    }

    static void buildOrderIterative(int root) {
        int[] stack = new int[N];
        int top = 0;
        stack[top++] = root;
        parent[root] = 0;
        int idx = 0;

        while (top > 0) {
            int u = stack[--top];
            order[idx++] = u;
            for (int v : g[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                stack[top++] = v;
            }
        }
    }
}
